public static long maxOperationsOnGraph(int N, int M, int[] u, int[] v, int[] W, long[] A) {
    long operations = 0;
    boolean piecesExist = true;

    while (piecesExist) {
        piecesExist = false;
        for (int i = 0; i < N; i++) {
            if (A[i] > 0) {
                piecesExist = true;
                A[i]--; // Remove one piece from vertex i
                long sumWeights = 0;
                for (int j = 0; j < M; j++) {
                    if (u[j] == i || v[j] == i) {
                        int adjacentVertex = (u[j] == i) ? v[j] : u[j];
                        if (sumWeights + W[adjacentVertex] < W[i]) {
                            A[adjacentVertex]++; // Place one piece on adjacent vertex
                            sumWeights += W[adjacentVertex];
                        }
                    }
                }
                operations++;
            }
        }
    }

    return operations;
}
